import os
from typing import Any, Dict, List, Optional

from azure.ai.formrecognizer import DocumentAnalysisClient
from azure.core.credentials import AzureKeyCredential


def _find_field(document: Dict[str, Any], *names: str) -> Optional[Any]:
    fields = document.get("fields", {})
    for name in names:
        if name in fields:
            return fields[name]
    return None


def _field_value(field: Any) -> Any:
    if field is None:
        return None
    for attr in (
        "value",
        "content",
        "value_string",
        "value_date",
        "value_currency",
        "value_number",
    ):
        if hasattr(field, attr):
            val = getattr(field, attr)
            if val is not None:
                return val
        if isinstance(field, dict) and attr in field and field[attr] is not None:
            return field[attr]
    return None


def _currency_amount(field: Any) -> Optional[float]:
    value = _field_value(field)
    if value is None:
        return None
    if hasattr(value, "amount"):
        return float(value.amount)
    if isinstance(value, dict) and "amount" in value:
        return float(value["amount"])
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _line_items(items_field: Any) -> List[Dict[str, Any]]:
    if items_field is None:
        return []

    items = getattr(items_field, "value", None)
    if items is None and isinstance(items_field, dict):
        items = items_field.get("value")
    if not items:
        return []

    results: List[Dict[str, Any]] = []
    for item in items:
        item_value = getattr(item, "value", None)
        if item_value is None and isinstance(item, dict):
            item_value = item.get("value", {})

        description = _field_value(item_value.get("Description")) if isinstance(item_value, dict) else None
        quantity = _field_value(item_value.get("Quantity")) if isinstance(item_value, dict) else None
        unit_price = _currency_amount(item_value.get("UnitPrice")) if isinstance(item_value, dict) else None
        amount = _currency_amount(item_value.get("Amount")) if isinstance(item_value, dict) else None
        product_code = _field_value(item_value.get("ProductCode")) if isinstance(item_value, dict) else None
        unit = _field_value(item_value.get("Unit")) if isinstance(item_value, dict) else None

        results.append(
            {
                "description": description,
                "quantity": quantity,
                "unit_price": unit_price,
                "amount": amount,
                "product_code": product_code,
                "unit": unit,
            }
        )
    return results


def extract_invoice_fields(invoice_path: str) -> Dict[str, Any]:
    endpoint = os.environ["AZURE_FORM_RECOGNIZER_ENDPOINT"]
    api_key = os.environ["AZURE_FORM_RECOGNIZER_KEY"]

    client = DocumentAnalysisClient(
        endpoint=endpoint,
        credential=AzureKeyCredential(api_key),
    )

    with open(invoice_path, "rb") as f:
        poller = client.begin_analyze_document(
            model_id="prebuilt-invoice",
            document=f,
        )
        result = poller.result()

    if not result.documents:
        return {
            "vendor": None,
            "date": None,
            "total": None,
            "line_items": [],
        }

    doc = result.documents[0]
    vendor_field = _find_field(doc, "VendorName", "MerchantName", "SupplierName")
    date_field = _find_field(doc, "InvoiceDate", "Date")
    total_field = _find_field(doc, "InvoiceTotal", "Total")
    items_field = _find_field(doc, "Items", "LineItems")

    date_value = _field_value(date_field)
    if hasattr(date_value, "isoformat"):
        date_value = date_value.isoformat()

    return {
        "vendor": _field_value(vendor_field),
        "date": date_value,
        "total": _currency_amount(total_field),
        "line_items": _line_items(items_field),
    }
